<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Brain, ArrowRight, Clock3, History } from 'lucide-vue-next'
import { usePagination } from '../lib/pagination'
import type { Deck, StudySession } from '../types'
import DeckCard from '../components/DeckCard.vue'
import EmptyState from '../components/EmptyState.vue'
import LoadState from '../components/LoadState.vue'
const selection = ref('own')
const decks = usePagination<Deck>(() => selection.value === 'own' ? '/decks' : '/saved')
const history = usePagination<StudySession>(() => '/study-sessions')
function select(value: string) { selection.value = value; void decks.load(true) }
onMounted(() => { void decks.load(true); void history.load(true) })
</script>
<template><div class="page-heading"><p class="eyebrow">UN MOMENT POUR VOUS</p><h1>On fait le point ?</h1><p>Quelques cartes, à votre rythme. Sans score, sans pression.</p></div><section class="study-intro surface"><span class="study-symbol"><Brain :size="32" /></span><div><h2>Choisissez votre prochaine découverte.</h2><p>Retournez les cartes, explorez les réponses et prenez le temps de comprendre.</p></div></section><div class="tabs" aria-label="Paquets disponibles"><button :class="{active:selection==='own'}" :aria-pressed="selection === 'own'" @click="select('own')">Mes paquets</button><button :class="{active:selection==='saved'}" :aria-pressed="selection === 'saved'" @click="select('saved')">Paquets enregistrés</button></div><div class="grid"><DeckCard v-for="deck in decks.items.value" :key="deck._id" :deck="deck"><RouterLink v-if="deck.cardCount" :to="`/study/${deck._id}`" class="btn btn-primary study-link">Réviser <ArrowRight :size="15" /></RouterLink><p v-else class="subtle empty-deck">Ajoutez une carte pour pouvoir réviser.</p></DeckCard></div><EmptyState v-if="!decks.busy.value && !decks.error.value && !decks.items.value.length" title="Le début d’une belle habitude." description="Créez un paquet ou enregistrez une découverte de la communauté pour commencer vos révisions."><RouterLink to="/create" class="btn btn-primary">Créer un paquet</RouterLink><RouterLink to="/feed" class="btn btn-secondary">Explorer</RouterLink></EmptyState><LoadState :busy="decks.busy.value" :error="decks.error.value" :more="decks.hasMore.value" @retry="decks.load(true)" @more="decks.load()" /><section class="history-section"><h2 class="section-title"><History :size="22" />Vos dernières sessions</h2><div class="surface history-list"><div v-for="session in history.items.value" :key="session._id" class="history-row"><span class="history-icon"><Clock3 :size="19" /></span><div><strong>{{ new Date(session.createdAt).toLocaleString('fr-FR', {dateStyle:'medium',timeStyle:'short'}) }}</strong><p>{{ session.cardsVisited }} cartes parcourues · environ {{ session.durationSeconds < 60 ? `${session.durationSeconds} s` : `${Math.round(session.durationSeconds / 60)} min` }}</p></div><RouterLink :to="`/decks/${session.deck}`" class="btn btn-ghost">Ouvrir <ArrowRight :size="15" /></RouterLink></div><p v-if="!history.busy.value && !history.error.value && !history.items.value.length" class="history-empty">Vos sessions terminées apparaîtront ici. Chaque petit pas compte.</p></div><p class="subtle history-help">Historique personnel. Les contenus ne sont pas conservés ici ; un paquet peut ne plus être accessible. Les durées sont approximatives, sans mesure de maîtrise.</p><LoadState :busy="history.busy.value" :error="history.error.value" :more="history.hasMore.value" @retry="history.load(true)" @more="history.load()" /></section></template>
<style scoped>.study-intro{padding:25px;display:flex;gap:22px;align-items:center;margin-bottom:28px}.study-symbol{display:grid;place-items:center;padding:18px;background:#f1edfd;color:#8d76c8;border-radius:17px}.study-intro h2{font-size:20px}.study-intro p{font-size:12px;color:var(--muted);margin-top:7px}.study-link{margin-top:18px;width:100%}.empty-deck{padding-top:15px}.history-section{margin-top:45px}.history-section h2{display:flex;align-items:center;gap:10px}.history-list{overflow:hidden}.history-row{display:flex;align-items:center;gap:15px;padding:20px;border-bottom:1px solid var(--border)}.history-row:last-child{border:0}.history-row strong{font-size:12px}.history-row p{font-size:11px;color:var(--muted);margin-top:4px}.history-row>.btn{margin-left:auto}.history-icon{display:grid;place-items:center;padding:12px;background:#f4f0fa;border-radius:13px;color:#9d88b2}.history-empty{padding:30px;color:var(--muted);font-size:13px}.history-help{margin-top:14px;font-size:11px}@media(max-width:600px){.study-intro{padding:20px;gap:15px}.study-symbol{padding:13px}.study-intro h2{font-size:17px}.history-row{padding:16px;gap:10px;flex-wrap:wrap}.history-icon{display:none}}
</style>